package store

import (
	"sort"
	"strings"
	"time"
)

// customerRetention is how long a deleted customer can be restored. PurgeDeletedCustomers removes it after that.
const customerRetention = 30 * 24 * time.Hour

// CreateCustomer adds a customer to an organization. A customer's email address is unique within the organization,
// ignoring case.
func (s *Store) CreateCustomer(orgID, name, email string, now time.Time) (Customer, error) {
	name, email = strings.TrimSpace(name), strings.TrimSpace(email)
	if name == "" || !validEmail(email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Customer{}, ErrNotFound
	}
	key := normEmail(email)
	if id, ok := s.customersByEmail[key]; ok && s.customers[id].OrgID == orgID {
		return Customer{}, ErrEmailTaken
	}
	c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: name, Email: email, CreatedAt: now.UTC()}
	s.customers[c.ID] = c
	s.customersByEmail[key] = c.ID
	return c, nil
}

// Customer returns one of an organization's customers that is not deleted.
func (s *Store) Customer(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerWithDeleted returns one of an organization's customers, deleted or not. Invoices and payments use it: they stay
// readable after their customer is deleted.
func (s *Store) CustomerWithDeleted(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerByID returns a customer of any organization (background jobs and the admin tool).
func (s *Store) CustomerByID(id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	return copyCustomer(c), ok
}

// Customers returns an organization's customers that are not deleted, oldest first.
func (s *Store) Customers(orgID string) []Customer {
	return s.orgCustomers(orgID, false)
}

// CustomersWithDeleted returns all of an organization's customers, deleted ones included, oldest first.
func (s *Store) CustomersWithDeleted(orgID string) []Customer {
	return s.orgCustomers(orgID, true)
}

func (s *Store) orgCustomers(orgID string, withDeleted bool) []Customer {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Customer{}
	for _, c := range s.customers {
		if c.OrgID == orgID && (withDeleted || c.DeletedAt == nil) {
			out = append(out, copyCustomer(c))
		}
	}
	sortCustomers(out)
	return out
}

// SearchCustomers returns an organization's customers that are not deleted and whose name or email contains q, ignoring
// case, oldest first.
func (s *Store) SearchCustomers(orgID, q string) []Customer {
	q = strings.ToLower(strings.TrimSpace(q))
	out := []Customer{}
	for _, c := range s.Customers(orgID) {
		if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
			out = append(out, c)
		}
	}
	return out
}

// FindCustomerByEmail returns the organization's customer that is not deleted and has this email address, ignoring case.
func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.customersByEmail[normEmail(email)]
	if !ok {
		return Customer{}, false
	}
	return copyCustomer(s.customers[id]), true
}

// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change, and a
// deleted customer cannot be changed.
func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.customers[id]
	if !ok || old.OrgID != orgID || old.DeletedAt != nil {
		return Customer{}, ErrNotFound
	}
	c := copyCustomer(old)
	if err := f(&c); err != nil {
		return Customer{}, err
	}
	c.ID, c.OrgID, c.CreatedAt, c.DeletedAt = old.ID, old.OrgID, old.CreatedAt, nil
	c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
	if c.Name == "" || !validEmail(c.Email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
		return Customer{}, invalid("a payment method looks like pm_...")
	}
	if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
		if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
			return Customer{}, ErrEmailTaken
		}
		delete(s.customersByEmail, normEmail(old.Email))
		s.customersByEmail[newKey] = c.ID
	}
	s.customers[id] = c
	return copyCustomer(c), nil
}

// DeleteCustomer deletes a customer now. See DeleteCustomerAt.
func (s *Store) DeleteCustomer(orgID, id string) error {
	return s.DeleteCustomerAt(orgID, id, time.Now())
}

// DeleteCustomerAt marks a customer deleted at now. The customer is hidden from the store's customer lookups, its email
// address becomes free, and it can be restored for 30 days (RestoreCustomer). Its invoices and payments stay. A customer
// with a subscription that is not canceled cannot be deleted: the error is ErrHasActiveSubscriptions.
func (s *Store) DeleteCustomerAt(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrHasActiveSubscriptions
		}
	}
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
	return nil
}

// RestoreCustomer undoes a customer's deletion when it was deleted no more than 30 days before now. It returns ErrNotFound
// for a customer that is not deleted or was deleted longer ago, and ErrEmailTaken when another customer now uses its email
// address.
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.Sub(*c.DeletedAt) > customerRetention {
		return Customer{}, ErrNotFound
	}
	key := normEmail(c.Email)
	if other, ok := s.customersByEmail[key]; ok && s.customers[other].OrgID == orgID {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes for good the customers deleted more than 30 days before now, and returns how many it
// removed. Their invoices and payments stay, but name no customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && now.Sub(*c.DeletedAt) > customerRetention {
			delete(s.customers, id)
			n++
		}
	}
	return n
}

// RemoveCustomer removes a customer at once, with no restore. It undoes a create that failed part way.
func (s *Store) RemoveCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	delete(s.customers, id)
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
	return nil
}

func copyCustomer(c Customer) Customer {
	if c.Metadata != nil {
		m := make(map[string]string, len(c.Metadata))
		for k, v := range c.Metadata {
			m[k] = v
		}
		c.Metadata = m
	}
	if c.DeletedAt != nil {
		t := *c.DeletedAt
		c.DeletedAt = &t
	}
	return c
}

func sortCustomers(cs []Customer) {
	sort.Slice(cs, func(i, j int) bool {
		if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
			return cs[i].CreatedAt.Before(cs[j].CreatedAt)
		}
		return cs[i].ID < cs[j].ID
	})
}

