func TestPlansAndSubscriptions(t *testing.T) {

func TestDeleteAndRestoreCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomerAt(a.ID, c.ID, t0); !errors.Is(err, ErrHasActiveSubscriptions) {
		t.Fatalf("deleted with an active subscription: %v", err)
	}
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	t1 := t0.Add(time.Hour)
	if err := s.DeleteCustomerAt(a.ID, c.ID, t1); err != nil {
		t.Fatal(err)
	}
	if _, ok := s.Customer(a.ID, c.ID); ok {
		t.Fatal("deleted customer is visible")
	}
	if got := s.Customers(a.ID); len(got) != 0 {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers = %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer found by email")
	}
	if got, ok := s.CustomerWithDeleted(a.ID, c.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(t1) {
		t.Fatalf("CustomerWithDeleted = %+v, %v", got, ok)
	}
	if got := s.CustomersWithDeleted(a.ID); len(got) != 1 || got[0].ID != c.ID {
		t.Fatalf("CustomersWithDeleted = %+v", got)
	}
	inv := Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}
	if _, err := s.CreateInvoice(inv, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active}, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, c.ID, func(*Customer) error { return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("update of a deleted customer: %v", err)
	}
	if err := s.DeleteCustomerAt(a.ID, c.ID, t1); !errors.Is(err, ErrNotFound) {
		t.Fatalf("second delete: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, c.ID, t1.Add(-time.Hour)); err == nil {
		t.Fatal("restored a customer that is not deleted")
	}

	// The email address is free again, so restoring is refused while another customer uses it.
	c2, err := s.CreateCustomer(a.ID, "Jane Two", "JANE@example.com", t1)
	if err != nil {
		t.Fatalf("email of a deleted customer not free: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, c.ID, t1); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if err := s.DeleteCustomerAt(a.ID, c2.ID, t1); err != nil {
		t.Fatal(err)
	}

	// Restoring works up to 30 days after the deletion, and not after.
	if _, err := s.RestoreCustomer(a.ID, c.ID, t1.Add(customerRetention+time.Second)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore after 30 days: %v", err)
	}
	r, err := s.RestoreCustomer(a.ID, c.ID, t1.Add(customerRetention))
	if err != nil || r.DeletedAt != nil {
		t.Fatalf("restore = %+v, %v", r, err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != c.ID {
		t.Fatalf("restored customer not found by email: %+v %v", got, ok)
	}

	// Purging removes only the customers deleted more than 30 days ago.
	c3, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	if err := s.DeleteCustomerAt(a.ID, c3.ID, t1); err != nil {
		t.Fatal(err)
	}
	if n := s.PurgeDeletedCustomers(t1.Add(customerRetention)); n != 0 {
		t.Fatalf("purged %d customers exactly 30 days after deletion", n)
	}
	if n := s.PurgeDeletedCustomers(t1.Add(customerRetention + time.Nanosecond)); n != 1 {
		t.Fatalf("purged %d customers, want 1", n)
	}
	if _, ok := s.CustomerWithDeleted(a.ID, c3.ID); ok {
		t.Fatal("purged customer still there")
	}
	if _, ok := s.CustomerWithDeleted(a.ID, c.ID); !ok {
		t.Fatal("a restored customer was purged")
	}

	// A deleted customer survives a snapshot, and its email address stays free.
	d, _ := s.CreateCustomer(a.ID, "Ben", "ben@example.com", t0)
	if err := s.DeleteCustomerAt(a.ID, d.ID, t1); err != nil {
		t.Fatal(err)
	}
	loaded, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := loaded.CustomerWithDeleted(a.ID, d.ID); !ok || got.DeletedAt == nil {
		t.Fatalf("deleted customer after a snapshot = %+v, %v", got, ok)
	}
	if _, ok := loaded.FindCustomerByEmail(a.ID, "ben@example.com"); ok {
		t.Fatal("deleted customer's email found after a snapshot")
	}
	if _, err := loaded.CreateCustomer(a.ID, "Ben Two", "ben@example.com", t1); err != nil {
		t.Fatalf("email of a deleted customer not free after a snapshot: %v", err)
	}
}

