func TestDeleteAndRestoreCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Pro", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)
	var inv struct {
		ID string `json:"id"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 500}}}, &inv)

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("get deleted: %s", r)
	}
	if r := e.Do("PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]string{"name": "Jane"}); r.Code != http.StatusNotFound {
		t.Fatalf("patch deleted: %s", r)
	}
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("delete deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}
	var page struct {
		Items []store.Customer `json:"items"`
	}
	for _, path := range []string{"/v1/customers", "/v1/customers?q=jane", "/v1/customers?email=jane@example.com"} {
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("%s lists the deleted customer: %+v", path, page.Items)
		}
	}
	if r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil); strings.Contains(string(r.Body), jane.ID) {
		t.Fatalf("export lists the deleted customer: %s", r.Body)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for deleted customer: %s", r)
	}
	var got map[string]any
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &got)
	if c, _ := got["customer"].(map[string]any); c["id"] != jane.ID || c["deleted"] != true {
		t.Fatalf("invoice customer = %v", got["customer"])
	}

	// The email address is free again, so restoring is refused while another customer uses it.
	ann := e.CreateCustomer(e.Acme, "Jane Two", "jane@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email taken: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+ann.ID, e.Acme.Key, nil, nil)
	var back store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &back)
	if back.ID != jane.ID || back.DeletedAt != nil {
		t.Fatalf("restore = %+v", back)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &back)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}

	// A restore is only possible for 30 days; after that the purge removes the customer and its invoice names none.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(30*24*time.Hour + time.Second)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("purged %d customers, want 1", n)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &got)
	if got["customer"] != nil {
		t.Fatalf("purged invoice's customer = %v", got["customer"])
	}
}

