149	// DeleteCustomerAt marks a customer deleted at now. The customer is hidden from the store's customer lookups, its email
150	// address becomes free, and it can be restored for 30 days (RestoreCustomer). Its invoices and payments stay. A customer
151	// with a subscription that is not canceled cannot be deleted: the error is ErrHasActiveSubscriptions.
152	func (s *Store) DeleteCustomerAt(orgID, id string, now time.Time) error {
153		s.mu.Lock()
154		defer s.mu.Unlock()
155		c, ok := s.customers[id]
156		if !ok || c.OrgID != orgID || c.DeletedAt != nil {
157			return ErrNotFound
158		}
159		for _, sub := range s.subs {
160			if sub.CustomerID == id && sub.Status != Canceled {
161				return ErrHasActiveSubscriptions
162			}
163		}
164		t := now.UTC()
165		c.DeletedAt = &t
166		s.customers[id] = c
167		if s.customersByEmail[normEmail(c.Email)] == id {
168			delete(s.customersByEmail, normEmail(c.Email))
169		}
170		return nil
171	}
