173	// RestoreCustomer undoes a customer's deletion when it was deleted no more than 30 days before now. It returns ErrNotFound
174	// for a customer that is not deleted or was deleted longer ago, and ErrEmailTaken when another customer now uses its email
175	// address.
176	func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
177		s.mu.Lock()
178		defer s.mu.Unlock()
179		c, ok := s.customers[id]
180		if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.Sub(*c.DeletedAt) > customerRetention {
181			return Customer{}, ErrNotFound
182		}
183		key := normEmail(c.Email)
184		if other, ok := s.customersByEmail[key]; ok && s.customers[other].OrgID == orgID {
185			return Customer{}, ErrEmailTaken
186		}
187		c.DeletedAt = nil
188		s.customers[id] = c
189		s.customersByEmail[key] = id
190		return copyCustomer(c), nil
191	}
