193	// PurgeDeletedCustomers removes for good the customers deleted more than 30 days before now, and returns how many it
194	// removed. Their invoices and payments stay, but name no customer.
195	func (s *Store) PurgeDeletedCustomers(now time.Time) int {
196		s.mu.Lock()
197		defer s.mu.Unlock()
198		n := 0
199		for id, c := range s.customers {
200			if c.DeletedAt != nil && now.Sub(*c.DeletedAt) > customerRetention {
201				delete(s.customers, id)
202				n++
203			}
204		}
205		return n
206	}
