// liveCustomerByEmail returns the ID of the organization's customer that is not deleted and has this normalized email
// address, or "". It scans the customers rather than trusting customersByEmail, which names one customer per address across
// all organizations and so can name another organization's customer.
func (s *Store) liveCustomerByEmail(orgID, key string) string {
	for id, c := range s.customers {
		if c.OrgID == orgID && c.DeletedAt == nil && normEmail(c.Email) == key {
			return id
		}
	}
	return ""
}

// indexEmail records id as the customer for an email address, unless another customer already holds that address in the
// index. It never overwrites another organization's entry.
func (s *Store) indexEmail(key, id string) {
	if _, taken := s.customersByEmail[key]; !taken {
		s.customersByEmail[key] = id
	}
}

