func TestRestoreCustomerChecksOnlyItsOwnOrg(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	const email = "shared@example.com"
	x, err := s.CreateCustomer(a.ID, "Old A", email, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomerAt(a.ID, x.ID, t0.Add(time.Hour)); err != nil {
		t.Fatal(err)
	}
	// A's live customer W takes the address; B's Z then uses it too.
	w, err := s.CreateCustomer(a.ID, "Live A", email, t0.Add(2*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	z, err := s.CreateCustomer(b.ID, "Other B", email, t0.Add(3*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(a.ID, x.ID, t0.Add(4*time.Hour)); !errors.Is(err, ErrEmailTaken) {
